/* TNM World Wrestling Report: ASW (All Star Wrestling).
   Everything the site shows for this promotion lives in this file. */

P.asw = {"short": "ASW", "name": "All Star Wrestling", "home": "United Kingdom", "c": "var(--asw)", "asOf": "1991-07-17", "status": "Four shows, four sellouts. Gary Albright beat Tony St. Clair 3–0 in a Skegness death match (****), and Robbie Brookside pinned Dave Taylor with Big Daddy in his corner. Haystacks is still champion and still never pinned. Kendo Nagasaki still hasn't debuted.", "stat": ["$20,000", "4 sold shows at $5,000"], "titles": [["British Heavyweight", "Giant Haystacks", "Beat Saint by countout (Bognor 7/6) and Brookside by DQ when Big Daddy interfered (Camber Sands 7/10). Never pinned."], ["British Heavy-Middleweight", "To establish", "Tournament proposed for Aug–Sep."], ["British Tag Team", "To establish", "Taylor & Finlay and Putski & Collins are the obvious teams."]], "factions": [["Taylor & Finlay", "Dave Taylor and Fit Finlay, the heel team. The promoter wants them kept together."], ["Putski & Collins", "Ivan Putski and Danny Boy Collins, babyfaces. Beat Taylor & Finlay at Bognor."], ["Big Daddy & Brookside", "Big Daddy made up for Camber Sands: he let Brookside take the pin on Dave Taylor at Skegness 7/17. Big Daddy vs. Haystacks at Prestatyn 7/24."], ["The Imports", "Backlund, Bruce Hart, Albright, Funk, Hamada, Parsons, Guerrero and Putski are the summer attractions."]], "stories": [["Albright's Death Match", "Gary Albright beat Tony St. Clair three falls to none at Skegness (****): two dragon suplexes and a countout.", "asw-albright-death-match-0717"], ["Big Daddy Keeps His Promise", "Big Daddy and Robbie Brookside beat Haystacks and Dave Taylor, and Big Daddy let Brookside take the pin. Haystacks still hasn't been pinned.", "asw-big-daddy-promise-0717"], ["Three Shows In", "Three sellouts, $15,000, a ***** 1/2 classic, a -*** 1/2 disaster and Big Daddy. The newsletter on the first week and a half of the camp tour."], ["Big Daddy Arrives", "Haystacks had Brookside trapped in the corner at Camber Sands when Big Daddy came through the crowd to save him. The referee disqualified Brookside, so Haystacks keeps the belt.", "asw-big-daddy-arrives-0710"], ["Regal Attacks Saint", "Johnny Saint beat Steve Regal with a cradle (***1/4). Regal jumped him after the bell and called his style music-hall wrestling.", "asw-regal-attacks-saint-0710"], ["The Backlund Challenge", "Backlund made Fit Finlay pass out in the chickenwing (****1/4). He's 3–0 with the match of the night on every show.", "asw-backlund-challenge-0710"], ["Albright vs. Putski", "Albright beat Putski with a German suplex at Camber Sands. The rematch is set for Prestatyn 7/24.", "asw-albright-putski-0710"], ["Backlund and Dean Steal Bognor", "Bob Backlund beat Doc Dean in 29:20 with a fisherman suplex at Bognor Regis. It rated *****1/2, the best match anywhere this month."], ["Haystacks Survives", "Johnny Saint had the champion in trouble and lost by countout. Haystacks keeps the belt. Robbie Brookside, who beat Tony St. Clair, is next."], ["The Camps Open", "Southport opened the tour: Backlund vs. Bruce Hart went ****3/4, Finlay beat Regal, and St. Clair and Hamada shook hands."], ["The Mystery Man", "Kendo Nagasaki is on the roster and still hasn't appeared. His Camber Sands and Skegness debuts were both cut.", "asw-mystery-man"]], "desk": ["Sonny Beach signed 7/19: 32-card non-exclusive deal (free to work other territories). Pay scale, card multiplier and debut To establish. Proposed debut vs. Hector Guerrero at Prestatyn 7/24 (plan).", "Prestatyn 7/24: Big Daddy vs. Haystacks heads it; Kendo Nagasaki finally debuts, vs. Danny Boy Collins (cut from the last two cards).", "Minehead 7/31: the British Heavy-Middleweight tournament is announced; Hector Guerrero (unused 7/17) is on the card.", "Business: every camp show is sold to the resort for a flat $5,000 and sells out at 1,200. Four shows, $20,000.", "Keep Haystacks under 10 minutes. His last three main events went 16:00, 20:09 and 16:03, all at ** or worse.", "Skull Murphy stays out of singles (-***1/2 and -*1/2). Iron Mike Sharpe is 0–3.", "Gary Albright won the three-falls death match 3–0 (****). Albright vs. Putski rematch at Prestatyn 7/24.", "Out until August: Dory Funk Jr. and Kroffat (AJPW to 7/27), Gran Hamada (NJPW to 7/30), Black Magic (CMLL).", "Dave Finlay: separate wrestler or duplicate?", "Territory plan for Jul–Dec is a draft awaiting approval."], "roster": [["Big Daddy", "13 cards · 1–0, first match 7/17"], ["Black Magic", "20 cards · working CMLL all July"], ["Bob Backlund", "38 cards · 3–0, special attraction"], ["Bruce Hart", "31 cards · 2–1"], ["Dan Kroffat", "28 cards · on AJPW tour to 7/27"], ["Danny Boy Collins", "22 cards · 1–1"], ["Dave Finlay", "43 cards · not used yet"], ["Dave Taylor", "14 cards · 0–2, w/ Fit Finlay"], ["Doc Dean", "41 cards · 2–1, rising"], ["Dory Funk Jr.", "20 cards · 0–1, on AJPW tour to 7/27"], ["El Gran Hamada", "31 cards · 0–1, on NJPW tour to 7/30"], ["Fit Finlay", "33 cards · 1–2, w/ Taylor"], ["Gary Albright", "43 cards · 2–1, beat St. Clair in a death match 7/17; Putski rematch 7/24"], ["Giant Haystacks", "48 cards · 3–1, champion, never pinned"], ["Hector Guerrero", "30 cards · 0–2"], ["Iceman King Parsons", "32 cards · 2–0"], ["Iron Mike Sharpe", "29 cards · 0–3"], ["Ivan Putski", "18 cards · 1–1"], ["Johnny Saint", "14 cards · 1–1, feuding with Regal"], ["Kendo Nagasaki", "23 cards · not used yet; Skegness debut cut 7/17"], ["Robbie Brookside", "48 cards · 3–1, pinned Taylor 7/17"], ["Skull Murphy", "24 cards · 0–2"], ["Sonny Beach", "32 cards · signed 7/19, non-exclusive · debut To establish"], ["Steve Regal", "30 cards · 2–2, feuding with Saint"], ["Tony St. Clair", "43 cards · 1–2"]], "departures": []};

E.push(...[{"d": "1991-07-03", "p": "asw", "link": "PONTINS_", "city": "Southport", "venue": "Pontins Southport", "type": "Holiday camp tour, Show 1", "gate": "1,200 (sellout) · $5,000 sold show", "rate": "**1/2", "m": [["Tony St. Clair vs. El Gran Hamada", "St. Clair (German suplex)", "**1/4"], ["Iceman King Parsons & Giant Haystacks vs. Gary Albright & Dory Funk Jr.", "Parsons & Haystacks (Haystacks side headlock on Albright)", "**1/4"], ["Doc Dean vs. Hector Guerrero", "Dean (magistral cradle)", "**1/2"], ["Bob Backlund vs. Bruce Hart", "Backlund (crossface chickenwing, Hart passed out)", "****3/4"], ["Robbie Brookside vs. Iron Mike Sharpe", "Brookside (bridging German suplex)", "*1/4"], ["Fit Finlay vs. Steve Regal", "Finlay (tombstone piledriver)", "**1/2"]], "n": ["Brian Dixon welcomed the crowd to the ASW Holiday Camp.", "St. Clair and Hamada shook hands."], "reads": [["The Camps Open", "asw-the-camps-open"], ["Observer: Three Shows In", "asw-observer-three-shows"]]}, {"d": "1991-07-06", "p": "asw", "link": "BUTLINS_", "city": "Bognor Regis", "venue": "Butlins Bognor Regis", "type": "Holiday camp tour, Show 2", "gate": "1,200 (sellout) · $5,000 sold show", "rate": "**1/4", "big": 1, "m": [["#1 contender: Robbie Brookside vs. Tony St. Clair", "Brookside (bridging German suplex)", "****1/4"], ["Bob Backlund vs. Doc Dean", "Backlund (fisherman suplex), 29:20", "*****1/2"], ["Ivan Putski & Danny Boy Collins vs. Dave Taylor & Fit Finlay", "Putski & Collins (Polish Hammer on Taylor)", "***1/4"], ["Steve Regal vs. Iron Mike Sharpe", "Regal (Regal Stretch)", "**"], ["Bruce Hart vs. Hector Guerrero", "Hart (running neckbreaker)", "**1/2"], ["British Heavyweight: Giant Haystacks (c) vs. Johnny Saint", "Haystacks by countout. Retains", "1/2*"]], "n": ["Brookside is the official #1 contender.", "Saint is owed a rematch with a clean finish."], "reads": [["Backlund and Dean Steal Bognor", "asw-backlund-dean"], ["Observer: Three Shows In", "asw-observer-three-shows"]]}, {"d": "1991-07-10", "p": "asw", "link": "THE_CAMB", "city": "Camber Sands", "venue": "Pontins Camber Sands", "type": "Holiday camp tour, Show 3", "gate": "1,200 (sellout) · $5,000 sold show", "rate": "**1/4", "big": 1, "m": [["Interview: Brian Dixon welcomes the camp and confirms the title match", "", ""], ["Doc Dean vs. Skull Murphy", "Dean (la magistral), 12:16. Murphy's debut", "-***1/2"], ["Gary Albright vs. Ivan Putski", "Albright (German suplex), 9:11. Rematch 7/24", "**1/4"], ["Johnny Saint vs. Steve Regal", "Saint (cradle gutbuster), 12:31. Regal attacks after", "***1/4"], ["Backlund Challenge: Bob Backlund vs. Fit Finlay", "Backlund (crossface chickenwing, Finlay passed out), 18:21", "****1/4"], ["British Heavyweight: Giant Haystacks (c) vs. Robbie Brookside", "Haystacks by DQ, 20:09. Big Daddy interfered to save Brookside. Retains", "*1/2"]], "n": ["Big Daddy's first appearance of the tour. His save got Brookside disqualified, so Haystacks retains.", "Match of the night: Backlund vs. Finlay. Backlund is 3–0.", "Kendo Nagasaki vs. Iron Mike Sharpe was cut before the show."], "reads": [["Observer report", "asw-observer-camber-0710"], ["Observer: Three Shows In", "asw-observer-three-shows"], ["From the Road: Robbie Brookside", "asw-diary-brookside-0710"]]}, {"d": "1991-07-17", "p": "asw", "city": "Skegness", "venue": "Butlins Skegness", "type": "Holiday camp tour, Show 4", "gate": "1,200 (sellout) · $5,000 sold show", "rate": "DUD", "ran": 1, "m": [["Death match, three falls: Gary Albright vs. Tony St. Clair", "ALBRIGHT 3–0 (dragon suplex 11:02, countout 17:26, dragon suplex 23:25)", "****"], ["Bruce Hart & Iceman King Parsons vs. Skull Murphy & Iron Mike Sharpe", "Parsons pins Sharpe (BUTT BUTT), 10:41", "-*1/2"], ["Steve Regal vs. Danny Boy Collins", "Regal, Collins passes out in the Regal Stretch, 15:14", "**3/4"], ["Main: Big Daddy & Robbie Brookside vs. Giant Haystacks & Dave Taylor", "Brookside pins Taylor (bridging German suplex), 16:03", "-*1/2"]], "n": ["Kendo Nagasaki vs. Hector Guerrero didn't run. Nagasaki still hasn't debuted.", "Brookside got the pin, not Big Daddy.", "Payroll $1,755 (12 worked). No injuries."], "reads": [["Albright Crushes St. Clair", "asw-albright-death-match-0717"], ["Observer report", "asw-observer-skegness-0717"], ["From the Road: Gary Albright", "asw-diary-albright-0717"]], "link": "SKEGNESS"}, {"d": "1991-07-24", "p": "asw", "city": "Prestatyn", "venue": "Pontins Prestatyn Sands", "type": "Holiday camp tour", "plan": 1, "m": [["Big Daddy vs. Giant Haystacks", "", ""]]}, {"d": "1991-07-31", "p": "asw", "city": "Minehead", "venue": "Butlins Minehead", "type": "Holiday camp tour", "plan": 1, "m": [["Heavy-Middleweight title tournament announced", "", ""]]}, {"d": "1991-08-02", "p": "asw", "city": "Bognor Regis", "venue": "Butlins Bognor Regis", "type": "Holiday camp tour"}, {"d": "1991-08-07", "p": "asw", "city": "Brean Sands", "venue": "Pontins Brean Sands", "type": "Holiday camp tour"}, {"d": "1991-08-14", "p": "asw", "city": "Ayr", "venue": "Butlins Ayr", "type": "Holiday camp tour"}, {"d": "1991-08-21", "p": "asw", "city": "Camber Sands", "venue": "Pontins Camber Sands", "type": "Holiday camp tour"}, {"d": "1991-08-28", "p": "asw", "city": "Skegness", "venue": "Butlins Skegness", "type": "Holiday camp tour"}]);

Object.assign(ARTICLES, {"asw-observer-three-shows": {"p": "asw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-11", "region": "UK Report", "kicker": "All Star Wrestling · The First Three Shows", "title": "Three Shows In", "dek": "Three sellouts, $15,000, the best match in the world this month and one of the worst. Bob Backlund can't do anything wrong, Giant Haystacks can't go 20 minutes, and Big Daddy has finally shown up.", "factTitle": "The Numbers", "facts": [["Shows", "Southport 7/3 · Bognor Regis 7/6 · Camber Sands 7/10"], ["Attendance", "3,600 (three sellouts of 1,200)"], ["Revenue", "$15,000 (three sold shows at $5,000)"], ["Talent payroll", "About $6,235 (42%)"], ["Cards", "**1/2 · **1/4 · **1/4"], ["Best match", "Backlund vs. Dean, *****1/2"], ["Worst match", "Dean vs. Murphy, -***1/2"]], "body": [["p", "All Star Wrestling is three shows into its summer holiday camp tour, and the business couldn't be simpler. Every show sells out the resort ballroom at 1,200 and every show is sold to the resort for a flat $5,000. That's 3,600 fans and $15,000 in eight days. Talent costs have run about $2,070 to $2,085 a night, roughly 42 percent of the fee, which leaves Brian Dixon a healthy margin on a tour that doesn't have to sell a single ticket. The pressure here isn't on the box office. It's on the matches, because these crowds are on holiday and they'll forget a bad night by breakfast, but the booker won't."], ["h", "The cards"], ["p", "Southport (7/3) rated **1/2, Bognor Regis (7/6) **1/4 and Camber Sands (7/10) **1/4. Those numbers are lower than the best matches deserve, and the reason is the same every night. The top of the card has been excellent, and the bottom has been dragging it down. Brookside vs. Iron Mike Sharpe went *1/4 at Southport, Haystacks vs. Johnny Saint was 1/2* in the Bognor main event, and Doc Dean vs. Skull Murphy opened Camber Sands at -***1/2, one of the worst ratings on any card in our world this month."], ["h", "Backlund"], ["p", "Bob Backlund has wrestled three times and had the match of the night three times. He beat Bruce Hart at Southport (****3/4), Doc Dean at Bognor in 29:20 (*****1/2, the best match anywhere this month) and Fit Finlay at Camber Sands (****1/4). Two of the three finished with the crossface chickenwing and the other man passing out. Dixon has turned him into an open challenge, the Backlund Challenge, and it's the best idea the tour has had. Every camp gets a former WWF Champion against one of the best British workers available, and the workers are rising to it. Dean in particular came out of Bognor a bigger star than he went in."], ["h", "The champion problem"], ["p", "Giant Haystacks is 3–0, still British Heavyweight Champion and still hasn't been pinned. He submitted Gary Albright with a side headlock in a Southport tag, beat Saint by countout at Bognor and beat Brookside by disqualification at Camber Sands. As a heel champion he's doing exactly what he should be. The fans hate him and they want him beaten. As a worker he's a problem. His two title defenses went 16:00 and 20:09 and rated 1/2* and *1/2. Nobody needs twenty minutes of Haystacks. Under ten, with a hot finish, is the ceiling."], ["h", "Big Daddy"], ["p", "The biggest story of the first week and a half happened in the last minute of Camber Sands. Haystacks had Brookside trapped in the corner and was squashing him when Big Daddy, who hadn't been seen on the tour, came through the crowd and into the ring to save him. The building came unglued. The referee disqualified Brookside for the interference, so in the record books Big Daddy's first appearance cost the young challenger his title shot. That's the setup for Skegness on 7/17, where Big Daddy and Brookside are expected to team against Haystacks and Dave Taylor. Big Daddy is 61. The smart booking is short matches and big moments, and he's still very good at the big moments."], ["h", "The undercard"], ["p", "Robbie Brookside earned the title shot by beating Tony St. Clair at Bognor (****1/4), easily his best match of the tour. He's 2–1 and the loss wasn't his fault. Johnny Saint has been robbed by Haystacks and then jumped by Steve Regal after beating him with a cradle at Camber Sands (***1/4). Regal called his style music-hall wrestling, and that gives Regal the feud he's needed since Finlay beat him at Southport. Gary Albright beat Ivan Putski with a German suplex at Camber Sands, which sets up a rematch at Prestatyn on 7/24. Skull Murphy's debut was a disaster and he shouldn't be in a singles match again until somebody has seen what he can do in a tag."], ["h", "What's missing"], ["p", "Kendo Nagasaki still hasn't appeared. His debut against Sharpe was on the Camber Sands card and was pulled before the show. Four of the summer imports are on other continents: Dory Funk Jr. and Dan Kroffat with All Japan until 7/27, El Gran Hamada with New Japan until 7/30, and Black Magic in Mexico, where he worked El Toreo the same night as Camber Sands. None of them should be expected in a holiday camp ballroom before August."], ["p", "Three shows in, the territory has everything a summer tour needs: a workrate attraction, a babyface the crowd adores in Saint, a champion they want to see lose, and now Big Daddy. The fix for the ratings is on the roster already. Keep the big men short, keep Murphy out of singles, and keep putting Backlund in the ring with the best people available."]]}, "asw-observer-camber-0710": {"p": "asw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-11", "region": "UK Report", "kicker": "All Star Wrestling · Pontins Camber Sands, July 10", "title": "Match Observations: Camber Sands", "dek": "Skull Murphy's debut goes badly, Albright and Putski are set for a rematch, Regal jumps Saint, and Big Daddy's first appearance saves Brookside and costs him the title match.", "factTitle": "The Numbers", "facts": [["Venue", "Pontins Camber Sands, Camber, East Sussex"], ["Date", "July 10, 1991 · Holiday camp tour, Show 3"], ["Attendance", "1,200 (sellout)"], ["Average ticket", "$4.17"], ["Gate", "$5,000 (flat fee, sold to the resort)"], ["Card", "**1/4"]], "body": [["p", "All Star Wrestling's third holiday camp show drew the usual sellout and rated **1/4, the same as Bognor. Two matches carried it and two dragged it down. It also had a debut, two programs set in motion and the first appearance of the summer by the biggest star in British wrestling."], ["p", "Brian Dixon opened with a short welcome and confirmed the title match. He told the crowd Haystacks wouldn't be allowed to hide on the outside this time, which set up the finish nicely."], ["p", "Skull Murphy made his ASW debut in the opener and lost to Doc Dean, who pinned him with the magistral cradle in 12:16. It went -***1/2, one of the worst ratings on any card in the world this month. Four days after Dean went 29 minutes with Backlund at *****1/2, he couldn't get anything out of Murphy, and twelve minutes was about nine too many. It's not the debut anyone wanted. Dean wasn't hurt by the result, but Murphy shouldn't be in a singles match again until we know what he can do. A tag match where someone else carries the work is the place to find out."], ["p", "Gary Albright pinned Ivan Putski with a German suplex in 9:11 for **1/4. It did its job. Albright looked like a powerhouse, Putski had the crowd behind him, and the result sets up a rematch at Pontins Prestatyn on July 24. The idea there is Putski getting his revenge with the Polish Hammer. Albright is 1-1 on the tour after submitting to Haystacks at Southport, and he needs this feud to establish what he is in this territory."], ["p", "Johnny Saint pinned Steve Regal with a cradle in 12:31. At ***1/4, it was the second-best match on the card and the best Regal has had on the tour. The story came after the bell. Regal attacked Saint from behind as he was celebrating, put the boots to him and left him lying, then told the crowd Saint's style was music-hall wrestling that belongs to the past. That's the start of a proper feud, and it's the one Regal has needed since Southport. Saint has now been robbed twice against Haystacks and attacked by Regal, and the camp crowds love him. He's the most sympathetic babyface on the tour."], ["p", "Bob Backlund made Fit Finlay pass out in the crossface chickenwing in 18:21. This was ****1/4, the match of the night again. That's ****3/4, *****1/2 and ****1/4 in his three matches on the tour, which is ridiculous for a ballroom tour. Finlay held up his end and lost nothing in defeat. The Backlund Challenge is working exactly as intended."], ["p", "The main event went 20:09 and rated *1/2. Haystacks spent most of it leaning on Robbie Brookside, and in the closing minutes he had Brookside trapped in the corner and was squashing the life out of him. That's when Big Daddy made his first appearance of the summer. He came through the crowd, through the ropes and straight at Haystacks to save Brookside, and the ballroom came unglued. He splashed Haystacks and chased him from the ring."], ["p", "Because Big Daddy interfered on Brookside's behalf, the referee disqualified Brookside. Haystacks keeps the title and is now 3-0 on the tour. Brookside took his first loss. In the moment nobody in the building cared: they'd just seen Big Daddy run Haystacks off. On paper, though, the rescue cost Brookside his title shot. That's a better story than the one that was drawn up, if it's handled right. Brookside can be frustrated without turning on anyone, and Big Daddy can make it up to him by teaming with him against Haystacks at Skegness on July 17."], ["p", "The problem is the length. Twenty minutes of Haystacks is too much for anyone, and the rating shows it. His matches need to stay under ten minutes for the rest of the summer, and Big Daddy's need to be shorter still."], ["p", "Three shows in, ASW has a workrate star in Backlund, a hot crowd act in Saint, a champion the fans genuinely want to see lose and, as of tonight, Big Daddy. It also has a booking problem: the bottom of the card keeps dragging the ratings down, and both of the last two main events have rated under **. The talent to fix that is already on the roster. It's a question of keeping the matches short where they need to be short."]]}, "asw-diary-brookside-0710": {"p": "asw", "series": "diary", "by": "Robbie Brookside", "date": "1991-07-10", "place": "Dressing room, Pontins Camber Sands", "kicker": "From the Road · Camber Sands, July 10", "title": "Twenty Minutes With Haystacks", "dek": "Robbie Brookside got his title shot, got saved by Big Daddy and got disqualified for it. His shoulder is purple.", "factTitle": "The Night", "facts": [["Show", "ASW holiday camp tour, Pontins Camber Sands"], ["Match", "Giant Haystacks (c) d. Robbie Brookside"], ["Finish", "DQ, 20:09. Big Daddy interfered"], ["Title", "British Heavyweight, Haystacks retains"]], "body": [["p", "I've had better nights. I've also had worse, so I'm trying to keep this in proportion."], ["p", "Mr. Dixon went out first and told the whole camp that Haystacks couldn't hide on the outside tonight. I stood behind the curtain thinking that's great, but it also means he's got nowhere to go except at me."], ["p", "Twenty minutes with him. Twenty. My shoulder's purple. I got him off his feet once with a dropkick and I swear the whole ballroom shook. I thought I had him. I really did. Then he got me in the corner and leaned on me, and I couldn't breathe, and the next thing I knew there was this roar like a train coming through the building."], ["p", "It was Big Daddy. I'd heard he was around but nobody told me he'd be coming tonight. He came through the ropes, splashed Haystacks and the referee just waved it off. I was disqualified. Me. I didn't even know what had happened until the referee told me in the ring."], ["p", "I'm not daft. Big Daddy saved me from getting flattened, and the campers went mental for him. But I wanted that belt, and I'd have liked a chance to win it myself."], ["p", "Big Daddy came up to me in the dressing room afterwards, shook my hand and said he owed me one. He says we're going to Skegness together next week to sort Haystacks out. I'll take that."], ["p", "Bob Backlund made Finlay pass out again tonight. That man is something else. Johnny Saint got a lovely win over Regal too. Doc's opener with Murphy was a bit of a mess. I won't say any more than that."], ["p", "Skegness is a week today. My shoulder had better be better by then."]]}, "asw-backlund-dean": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-08", "region": "UK Report", "kicker": "All Star Wrestling · Butlins Bognor Regis · July 6", "title": "Backlund and Dean Steal Bognor", "dek": "Bob Backlund and Doc Dean went 29 minutes at a holiday camp and had the best match anywhere in the world this month.", "body": [["p", "The second show of All Star's summer camp tour, at Butlins in Bognor Regis on July 6, had a match nobody will forget. Bob Backlund beat Doc Dean in 29:20 with a fisherman suplex, and it rated *****1/2. That's the best match in any promotion this month, at a holiday camp."], ["p", "Backlund is the tour's special attraction and has had the match of the night on both shows. At Southport on July 3 he made Bruce Hart pass out in the crossface chickenwing in a ****3/4 match. Against Dean, he got a longer, more even match, and Dean came out of it looking like a top babyface even in defeat."], ["h", "What it means"], ["p", "Dean is 1–1 on the tour and was already one of the promotion's rising faces. After this, he's the obvious man to get a rematch with Backlund before the camp season ends. The promoter's notes after Bognor said exactly that: keep building Dean off this match."]], "facts": [["Match", "Bob Backlund d. Doc Dean"], ["Time", "29:20"], ["Finish", "Fisherman suplex"], ["Rating", "*****1/2"], ["Backlund", "2–0 on the tour"], ["Southport", "vs. Bruce Hart, ****3/4"]], "factTitle": "The Match"}, "asw-haystacks-survives": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-08", "region": "UK Report", "kicker": "All Star Wrestling · British Heavyweight Championship", "title": "Haystacks Survives", "dek": "Johnny Saint had Giant Haystacks in trouble and lost by countout. The champion keeps the belt, and Robbie Brookside is next.", "body": [["p", "Giant Haystacks is still the British Heavyweight Champion, but not by much. In the Bognor Regis main event on July 6, Johnny Saint had him in trouble and then lost by countout at 16:00. It wasn't much of a match on paper at 1/2*, but the finish did its job: Saint was protected, and the crowd went home wanting to see him get another shot."], ["p", "He may have to wait. Robbie Brookside beat Tony St. Clair with a bridging German suplex earlier on the card in a ****1/4 match and is now the official number one contender. Brookside is 2–0 on the tour and is clearly being built as the future of the promotion."], ["h", "What's next"], ["p", "Haystacks vs. Brookside for the title is made. Saint vs. Haystacks with a clean finish is the rematch the promoter wants. And Big Daddy, who is on the roster and hasn't been used, is the name every camp crowd wants to see in the ring with Haystacks."]], "facts": [["Champion", "Giant Haystacks"], ["Retained vs.", "Johnny Saint, countout"], ["Next challenger", "Robbie Brookside"], ["Brookside", "2–0, beat St. Clair ****1/4"], ["Waiting", "Big Daddy"]], "factTitle": "The Title"}, "asw-the-camps-open": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-05", "region": "UK Report", "kicker": "All Star Wrestling · Pontins Southport · July 3", "title": "The Camps Open", "dek": "All Star's summer tour started at Pontins Southport with Bob Backlund, Bruce Hart and a lot of imports.", "body": [["p", "All Star Wrestling opened its 1991 holiday camp tour at Pontins Southport on July 3. Brian Dixon welcomed the crowd, and the card was built around the summer imports. Bob Backlund made Bruce Hart pass out in the crossface chickenwing in 23:28, a ****3/4 match that was easily the best thing on the show."], ["p", "Fit Finlay beat Steve Regal with a tombstone piledriver in the main event. Giant Haystacks and Iceman King Parsons beat Gary Albright and Dory Funk Jr. when Haystacks put Albright away with a side headlock. Doc Dean cradled Hector Guerrero, and Tony St. Clair beat El Gran Hamada, then shook his hand."], ["h", "The imports"], ["p", "The camp crowds are on holiday and want names, which is why the roster is full of visitors: Backlund, Hart, Albright, Funk, Hamada, Parsons, Guerrero and Ivan Putski. Several of them are also working in Japan this summer. Funk and Dan Kroffat are on All Japan's tour through July 27, and Hamada is with New Japan through July 30, so the July cards will lean on the rest."]], "facts": [["Card", "**1/2"], ["Best match", "Backlund vs. Bruce Hart, ****3/4"], ["Main event", "Finlay d. Regal"], ["Next", "Butlins Bognor Regis, 7/6"]], "factTitle": "Southport"}, "asw-two-passports": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "UK Report", "kicker": "All Star Wrestling · Backstage", "title": "Two Passports", "dek": "Black Magic is on the All Star Wrestling roster and hasn't worked a single camp date. He's been in Mexico City instead.", "body": [["p", "Black Magic, who is British, is listed on the All Star Wrestling roster for the 1991 holiday camp season. He hasn't been on any of the first three camp cards, and the reason is simple: he's been in Mexico, working as one of CMLL's foreign rudos alongside Vampiro Canadiense and Kamala."], ["p", "It hasn't been a great month for him on the scoreboard. He's 0–3 in CMLL, losing a DQ when he threw Atlantis over the top rope, losing to Negro Casas in Puebla and then losing to Atlantis again at El Toreo. But the Casas match went 26 minutes and was the best thing on that show at ****1/2, and the Puebla office wants it back."], ["h", "The schedule"], ["p", "All Star runs Wednesdays at the camps. CMLL has Black Magic on Saturday the 13th and Friday the 19th, which makes a Skegness date in between unrealistic. The best guess is that he stays in Mexico through Verano de Escándalo on July 26 and comes home in August, where ASW wants him and Skull Murphy as the regular heel team against the touring babyfaces."]], "facts": [["Home", "All Star Wrestling (UK)"], ["Working", "CMLL, foreign rudos"], ["CMLL record", "0–3"], ["Best match", "vs. Negro Casas, ****1/2"], ["ASW plan", "Heel team with Skull Murphy, August"]], "factTitle": "Black Magic"}, "asw-albright-death-match-0717": {"p": "asw", "kicker": "All Star Wrestling · Butlins Skegness, July 17", "title": "Albright Crushes St. Clair in Skegness Death Match", "dek": "Gary Albright takes all three falls from Tony St. Clair, Big Daddy lets Brookside take the pin, and Kendo Nagasaki keeps the campers waiting.", "by": "All Star Wrestling", "date": "1991-07-17", "factTitle": "Skegness Results", "facts": [["Death match", "Albright d. St. Clair, 3 falls to 0"], ["Main", "Big Daddy & Brookside d. Haystacks & Taylor"], ["Also", "Regal d. Collins; Hart & Parsons d. Murphy & Sharpe"], ["Crowd", "1,200 (sellout)"]], "body": [["p", "They called it a death match, three falls to a finish, and by the end of it Tony St. Clair looked like he'd been in one. Gary Albright, the giant American with the frightening suplexes, didn't drop a single fall. He took the first with the dragon suplex at 11:02, the second when St. Clair couldn't beat the count at 17:26, and the third with another dragon suplex at 23:25. St. Clair never quit, and the Skegness campers gave him a standing ovation as he was helped to the dressing room."], ["h", "BIG DADDY KEEPS HIS PROMISE"], ["p", "At Camber Sands, Big Daddy's rescue cost Robbie Brookside his chance at the British Heavyweight Championship. Big Daddy promised to make it up to him, and tonight he did. With Giant Haystacks and Dave Taylor across the ring, Big Daddy did the heavy lifting and kept the champion busy, then stood back and let his young partner take the glory. Brookside caught Taylor with a bridging German suplex at 16:03, and Big Daddy hoisted him onto his shoulders. Haystacks stormed off without a word. They meet one on one at Prestatyn next week."], ["h", "REGAL STRETCHES COLLINS"], ["p", "Steve Regal is in a foul mood since Johnny Saint embarrassed him at Camber Sands, and Danny Boy Collins paid for it. Regal tied him in the Regal Stretch and Collins passed out at 15:14. Regal refused to release the hold until the referee pulled him off."], ["h", "THE BUTT BUTT"], ["p", "The Iceman King Parsons and Bruce Hart beat Skull Murphy and Iron Mike Sharpe when Parsons flattened Sharpe with his famous BUTT BUTT at 10:41. The children in the front rows did the Iceman's dance all the way to the interval."], ["h", "STILL WAITING"], ["p", "Kendo Nagasaki did not appear in Skegness. The promoter apologised to the crowd and promised the masked man will make his debut very soon."]]}, "asw-observer-skegness-0717": {"p": "asw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-17", "region": "UK Report", "kicker": "All Star Wrestling · Butlins Skegness, July 17", "title": "Match Observations: Skegness", "dek": "Albright and St. Clair go **** in a three-falls death match, the rest of the card sinks it to DUD, and Kendo Nagasaki is a no-show again.", "factTitle": "The Numbers", "facts": [["Venue", "Butlins Skegness, Skegness, Lincolnshire"], ["Date", "July 17, 1991 · Holiday camp tour, Show 4"], ["Attendance", "1,200 (sellout)"], ["Average ticket", "$4.17"], ["Gate", "$5,000 (flat fee, sold to the resort)"], ["Talent payroll", "$1,755 (35%)"], ["Card", "DUD"]], "body": [["p", "Fourth show, fourth sellout, and the worst card of the tour. Skegness came in at DUD overall even with a **** match in it. Three of the four matches were bad, and two of them were very bad. Business is the same as always: 1,200 campers and a flat $5,000 from the resort. That's $20,000 from four shows. Payroll for the night was about $1,755 for twelve men, 35% of the fee."], ["p", "The good match was the one nobody expected anything from. Tony St. Clair and Gary Albright were set for a regular match, but Albright asked Brian Dixon to make it a death match, three falls, and St. Clair agreed to it on the night. Albright won 3-0 in 23:25 with two dragon suplexes and a countout in between, ****. It's Albright's best match on the tour and it makes him the most credible heel on the roster after Haystacks. St. Clair loses nothing for going 23 minutes. Albright is 2-1 now and gets Putski at Prestatyn."], ["p", "The main event was -*1/2. Haystacks, Taylor, Big Daddy and Brookside went 16:03, and the word all week was to keep Haystacks under ten minutes. Big Daddy works in short bursts and Haystacks doesn't work at all over long ones. Brookside got the pin on Taylor with the bridging German suplex, which is the right finish. Big Daddy giving him the pin is his way of making up for the DQ at Camber Sands, and it keeps Brookside at the front of the line for Haystacks' title. Big Daddy vs. Haystacks is next week at Prestatyn. Keep it short."], ["p", "Bruce Hart & Parsons beat Skull Murphy & Iron Mike Sharpe at -*1/2. Murphy has now been in two matches for All Star and they've rated -***1/2 and -*1/2. Keeping him out of singles hasn't helped. Sharpe is 0-3."], ["p", "Regal made Danny Boy Collins pass out in the Regal Stretch at **3/4, the only other watchable match. Regal is 2-2 and building toward Saint & Dean vs. Regal & Finlay at Prestatyn."], ["p", "Kendo Nagasaki still hasn't debuted. This is the second time he's been advertised and didn't wrestle. The story going around is that Nagasaki won't make his first appearance in the middle of a camp card and is holding out for a main-event debut. Hector Guerrero, who was supposed to be his opponent, wasn't used either. At some point the camps stop believing he exists."], ["p", "1. Death match, three falls: Gary Albright beat Tony St. Clair 3-0 in 23:25. Dragon suplex at 11:02, countout at 17:26, dragon suplex at 23:25. ****"], ["p", "2. Bruce Hart & Iceman King Parsons beat Skull Murphy & Iron Mike Sharpe in 10:41 when Parsons pinned Sharpe with the BUTT BUTT. -*1/2"], ["p", "3. Steve Regal beat Danny Boy Collins in 15:14 when Collins passed out in the Regal Stretch. **3/4"], ["p", "4. Big Daddy & Robbie Brookside beat Giant Haystacks & Dave Taylor in 16:03 when Brookside pinned Taylor with a bridging German suplex. -*1/2"], ["p", "Overall card: DUD"], ["p", "Next is Prestatyn on 7/24: Big Daddy vs. Haystacks, Backlund vs. Bruce Hart and Albright vs. Putski."]]}, "asw-diary-albright-0717": {"p": "asw", "series": "diary", "by": "Gary Albright", "date": "1991-07-17", "place": "A chalet at Butlins Skegness", "kicker": "From the Road · Skegness, July 17", "title": "Three Falls and a Kettle", "dek": "Gary Albright asks for a death match with Tony St. Clair, gets one, and wins all three falls.", "factTitle": "The Night", "facts": [["Show", "Holiday camp tour, Skegness"], ["Match", "Gary Albright d. Tony St. Clair"], ["Finish", "Death match, 3 falls to 0"], ["Rating", "****"], ["Next", "Ivan Putski, Prestatyn 7/24"]], "body": [["p", "The chalet has two beds, a kettle and a radiator that comes on whenever it wants to. It's July. Outside the window there's a go-kart track and a sign for the Redcoats' talent show. I'm a long way from home."], ["p", "They had me down for a regular match with Tony St. Clair tonight. I asked Dixon this afternoon if we could make it something worth remembering, and he said Tony would have to agree. Tony said yes before Dixon finished the sentence. That's the kind of guy he is. They call it a death match over here. Three falls. You have to win all of them."], ["p", "I threw him with the dragon suplex for the first one and I could tell he felt it. He came back hard in the second, kept me down on the mat with headlocks and made me work for every inch. Then I got him over the top rope and he couldn't get back in before ten. I've been in a lot of rings, but I've never heard a crowd of holiday campers boo like that. The third fall I just kept throwing him until he couldn't get up. Dragon suplex again. Twenty-three minutes."], ["p", "He shook my hand in the back with ice on his neck. He said, \"Good lad.\" I think that's a compliment."], ["p", "The rest of the show I watched from behind the curtain. Big Daddy carried his partner on his shoulders around the ring after the main and the kids went crazy. Haystacks walked past me in the corridor and the whole wall shook."], ["p", "Next week is Prestatyn and Ivan Putski. He's going to want to make up for Camber Sands. The kettle's on. Two sugars."]]}, "asw-sonny-beach-signs-0719": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-19", "region": "UK Report", "kicker": "All Star · News", "title": "Sonny Beach Signs with All Star", "dek": "All Star Wrestling adds Sonny Beach on a 32-card deal that leaves him free to work elsewhere.", "factTitle": "The Deal", "facts": [["Wrestler", "Sonny Beach"], ["Signed", "July 19, 1991"], ["Length", "32 cards"], ["Terms", "Non-exclusive"], ["Debut", "To establish"]], "body": [["p", "Brian Dixon's All Star Wrestling has signed Sonny Beach to a 32-card contract. The deal is non-exclusive, so Beach is free to keep working for other promotions while he's under contract to All Star."], ["p", "His debut date hasn't been announced. The holiday camp tour goes to Pontins Prestatyn next Wednesday, 7/24."]]}});

CONTRACTS.asw = {"basis": "Per show", "unit": "per appearance", "revenue": "Every holiday camp show sells out at 1,200 and is sold to the resort for a flat $5,000.", "target": "About $2,000 a show (40%) across a card of 10–12 workers.", "how": "Flat fee for each show worked. All shows pay the same because every show earns the same $5,000. Imports booked from Japan, Mexico or the U.S. are paid only for the dates they're in Britain. Managers and announcers are on the same scale.", "classes": [], "rows": [["A", "Big Daddy", 350, "Legend, not used yet"], ["A", "Giant Haystacks", 350, "British Heavyweight Champion"], ["A", "Bob Backlund", 300, "Special attraction"], ["B", "Kendo Nagasaki", 200, ""], ["B", "Ivan Putski", 175, "Big draw with holidaymakers"], ["B", "Johnny Saint", 175, ""], ["B", "Dory Funk Jr.", 175, "Import, AJPW to 7/27"], ["B", "Robbie Brookside", 150, "#1 contender"], ["B", "Fit Finlay", 150, ""], ["C", "Steve Regal", 125, ""], ["C", "Gary Albright", 125, "Import"], ["C", "El Gran Hamada", 125, "Import, NJPW to 7/30"], ["C", "Doc Dean", 100, ""], ["C", "Tony St. Clair", 100, ""], ["C", "Dave Taylor", 100, ""], ["C", "Bruce Hart", 100, "Import"], ["C", "Dan Kroffat", 100, "Import, AJPW to 7/27"], ["C", "Iceman King Parsons", 100, "Import"], ["C", "Sonny Beach", 100, "Signed 7/19, non-exclusive"], ["D", "Danny Boy Collins", 85, ""], ["D", "Skull Murphy", 85, ""], ["D", "Hector Guerrero", 85, ""], ["D", "Iron Mike Sharpe", 85, ""], ["D", "Black Magic", 85, "Also CMLL"], ["D", "Dave Finlay", 60, ""], ["O", "TBD: MC / ring announcer", 40, "Name to be set"]], "total": 3625, "check": "The first three camp shows paid $2,070, $2,080 and $2,085 in talent: about 42% of the $5,000 fee."};

FINANCE.asw = {"period": "Per show", "payBasis": "Per show", "rows": [{"d": "1991-07-03", "show": "Southport · Holiday camp tour, Show 1", "cls": "Regular", "gate": 5000, "payroll": 2070, "note": "14 on the card"}, {"d": "1991-07-06", "show": "Bognor Regis · Holiday camp tour, Show 2", "cls": "Regular", "gate": 5000, "payroll": 2080, "note": "14 on the card"}, {"d": "1991-07-10", "show": "Camber Sands · Holiday camp tour, Show 3", "cls": "Regular", "gate": 5000, "payroll": 2085, "note": "11 on the card, including Big Daddy's appearance"}, {"d": "1991-07-17", "show": "Skegness · Holiday camp tour, Show 4", "cls": "Regular", "gate": 5000, "payroll": 1755, "note": "12 on the card"}], "note": "Every holiday camp show is sold to the resort for a flat $5,000."};

