Object.assign(ARTICLES, {"asw-big-daddy-promise-0717": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-17", "region": "UK Report", "kicker": "All Star Wrestling · Butlins Skegness, July 17", "title": "Big Daddy Keeps His Promise", "dek": "Big Daddy teamed with Robbie Brookside against Giant Haystacks, and let the young man take the pin.", "body": [["p", "After saving Robbie Brookside from Giant Haystacks at Camber Sands, Big Daddy stood beside him at Skegness: Big Daddy and Brookside beat Haystacks and Dave Taylor when Brookside pinned Taylor with the bridging German suplex at 16:03."], ["p", "Big Daddy could have taken the fall himself and the crowd would have cheered it. He let Brookside have it. Haystacks still hasn't been pinned and still holds the British Heavyweight belt, but Brookside is closer to him than anyone else on the roster."]], "facts": [["Match", "Big Daddy & Brookside d. Haystacks & Taylor"], ["Finish", "Brookside pins Taylor, German suplex, 16:03"], ["Haystacks", "still never pinned"], ["Title", "Haystacks still British Heavyweight Champion"], ["Crowd", "1,200, sellout"]], "factTitle": "The Match"}, "asw-big-daddy-arrives-0710": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-10", "region": "UK Report", "kicker": "All Star Wrestling · Pontins Camber Sands, July 10", "title": "Big Daddy Arrives", "dek": "Giant Haystacks had Robbie Brookside trapped in the corner. Then Big Daddy came through the crowd.", "body": [["p", "Robbie Brookside earned his British Heavyweight title shot by beating Tony St. Clair at Bognor Regis. At Camber Sands, Giant Haystacks had him trapped in the corner and was taking him apart when Big Daddy came through the crowd to pull him out. The referee disqualified Brookside for the interference at 20:09, and Haystacks kept the belt (*1/2)."], ["p", "It was Big Daddy's first appearance of the summer, and the camp went up for it. The DQ cost Brookside the title, but it put Big Daddy and Haystacks on a collision course again."]], "facts": [["Match", "Haystacks (c) vs. Robbie Brookside"], ["Result", "Haystacks by DQ, 20:09"], ["Why", "Big Daddy saved Brookside"], ["Title", "Haystacks retains"], ["Crowd", "1,200, sellout"]], "factTitle": "The Title Match"}, "asw-regal-attacks-saint-0710": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-10", "region": "UK Report", "kicker": "All Star Wrestling · Pontins Camber Sands, July 10", "title": "Regal Attacks Saint", "dek": "Johnny Saint beat Steve Regal with a cradle. Regal jumped him after and called it music-hall wrestling.", "body": [["p", "Johnny Saint beat Steve Regal with a cradle gutbuster at Camber Sands in 12:31 (***1/4), out-wrestling the younger man at his own game. Regal didn't take it well. He jumped Saint after the bell and told the camp that Saint's style was music-hall wrestling, fit for a holiday crowd and nothing else."], ["p", "Regal took it out on Danny Boy Collins at Skegness, making him pass out in the Regal Stretch. A rematch with Saint is the obvious next step."]], "facts": [["Match", "Johnny Saint d. Steve Regal"], ["Finish", "cradle gutbuster, 12:31"], ["Rating", "***1/4"], ["After", "Regal attacks Saint"], ["Next", "rematch To establish"]], "factTitle": "The Match"}, "asw-backlund-challenge-0710": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-10", "region": "UK Report", "kicker": "All Star Wrestling · Pontins Camber Sands, July 10", "title": "The Backlund Challenge", "dek": "Bob Backlund made Fit Finlay pass out in the chickenwing, and he has the match of the night on every show.", "body": [["p", "Bob Backlund's open challenge drew Fit Finlay at Camber Sands, and Finlay lasted 18:21 before he passed out in the crossface chickenwing (****1/4). It's the third time this summer Backlund has stolen the show. He made Bruce Hart pass out at Southport (****3/4) and beat Doc Dean in 29:20 at Bognor Regis."], ["p", "He's 3–0. ASW hasn't put him near a title yet, and on these numbers it may have to."]], "facts": [["July 3", "d. Bruce Hart, chickenwing, ****3/4"], ["July 6", "d. Doc Dean, 29:20"], ["July 10", "d. Fit Finlay, chickenwing, 18:21, ****1/4"], ["Record", "3–0"], ["Next", "To establish"]], "factTitle": "The Record"}, "asw-albright-putski-0710": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-10", "region": "UK Report", "kicker": "All Star Wrestling · Pontins Camber Sands, July 10", "title": "Albright vs. Putski", "dek": "Gary Albright beat Ivan Putski with the German suplex, and the rematch is set for Prestatyn.", "body": [["p", "Gary Albright beat Ivan Putski with the German suplex at Camber Sands in 9:11 (**1/4). Putski and Danny Boy Collins had beaten Dave Taylor and Fit Finlay at Bognor Regis with the Polish Hammer, but he had no answer for Albright's suplexes."], ["p", "Albright followed it with a three-falls-to-none death match win over Tony St. Clair at Skegness (****). The Putski rematch is set for Prestatyn on July 24."]], "facts": [["Match", "Gary Albright d. Ivan Putski"], ["Finish", "German suplex, 9:11"], ["Rating", "**1/4"], ["Rematch", "Prestatyn, July 24"], ["Since", "Albright d. St. Clair 3–0, Skegness"]], "factTitle": "The Match"}, "asw-mystery-man": {"p": "asw", "news": 1, "by": "Newsletter staff", "date": "1991-07-17", "region": "UK Report", "kicker": "All Star Wrestling · Holiday camp tour", "title": "The Mystery Man", "dek": "Kendo Nagasaki is on the ASW roster. Nobody has seen him yet.", "body": [["p", "Kendo Nagasaki is under contract to All Star Wrestling and has been advertised twice. His debut was cut from Camber Sands, then cut again from Skegness. He hasn't appeared in any form."], ["p", "In British wrestling the mystery is part of the act, and the camps haven't complained yet. When he finally turns up is To establish."]], "facts": [["Who", "Kendo Nagasaki"], ["Status", "on the roster"], ["Cut", "Camber Sands, Skegness"], ["Appearances", "none"], ["Debut", "To establish"]], "factTitle": "The Situation"}});
